      isHot: attachedDatabase.typeMapping.read(
        DriftSqlType.bool,
        data['${effectivePrefix}is_hot'],
      )!,
      likeCount: attachedDatabase.typeMapping.read(
        DriftSqlType.int,
        data['${effectivePrefix}like_count'],
      )!,
      commentCount: attachedDatabase.typeMapping.read(
        DriftSqlType.int,
        data['${effectivePrefix}comment_count'],
      )!,
      likedAt: attachedDatabase.typeMapping.read(
        DriftSqlType.int,
        data['${effectivePrefix}liked_at'],
      ),
      authorResidentId: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}author_resident_id'],
      ),
      speechBy: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}speech_by'],
      )!,
      voicePath: attachedDatabase.typeMapping.read(
        DriftSqlType.string,
        data['${effectivePrefix}voice_path'],
      ),
      speechDurationMs: attachedDatabase.typeMapping.read(
        DriftSqlType.int,
        data['${effectivePrefix}speech_duration_ms'],
      ),
    );
  }

  @override
  $PostsTable createAlias(String alias) {
    return $PostsTable(attachedDatabase, alias);
  }
}

class PostRow extends DataClass implements Insertable<PostRow> {
  final String id;
  final String content;
  final String images;
  final int createdAt;
  final int? updatedAt;
  final String scope;
  final bool isAiGenerated;
  final int? deletedAt;
  final String? topicId;
  final String? topicName;
  final bool allowAiReply;
  final String? replyDensity;
  final String? likeLevel;
  final int? humanLevel;
  final bool isHot;
  final int likeCount;
  final int commentCount;

  /// 我点过赞的时刻；null 表示没点过。
  ///
  /// 存时刻而不是布尔值，是因为"什么时候点的"以后可能有用（比如排序、
  /// 比如看自己的互动轨迹）；而它反正只占一个整数。
  final int? likedAt;

  /// 固定住民自己发的动态记的是他的 id；用户发的为空。
  ///
  /// 不设外键：固定住民可以被删除（软删除），而动态要留着；
  /// 而且这一列只回答"谁发的"，不承担级联语义。
  final String? authorResidentId;

  /// 这条是“用语音发的”吗（v4.0）。
  ///
  /// 空串 = 打字发的；`me` = 用户自己的语音；其余 = 固定住民的 id。
  /// 正文仍然是转写后的文字，这个字段只负责在界面上标一句“来自 XX 的语音”。
  final String speechBy;

  /// 用户语音帖的原始音频（`file:` 引用）。住民语音帖只有转写稿，没有文件。
  final String? voicePath;
  final int? speechDurationMs;
  const PostRow({
    required this.id,
    required this.content,
    required this.images,
    required this.createdAt,
    this.updatedAt,
    required this.scope,
    required this.isAiGenerated,
    this.deletedAt,
    this.topicId,
    this.topicName,
    required this.allowAiReply,
    this.replyDensity,
    this.likeLevel,
    this.humanLevel,
    required this.isHot,
    required this.likeCount,
    required this.commentCount,
    this.likedAt,
    this.authorResidentId,
    required this.speechBy,
    this.voicePath,
    this.speechDurationMs,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['content'] = Variable<String>(content);
    map['images'] = Variable<String>(images);
    map['created_at'] = Variable<int>(createdAt);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<int>(updatedAt);
    }
    map['scope'] = Variable<String>(scope);
    map['is_ai_generated'] = Variable<bool>(isAiGenerated);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<int>(deletedAt);
    }
    if (!nullToAbsent || topicId != null) {
      map['topic_id'] = Variable<String>(topicId);
    }
    if (!nullToAbsent || topicName != null) {
      map['topic_name'] = Variable<String>(topicName);
    }
    map['allow_ai_reply'] = Variable<bool>(allowAiReply);
    if (!nullToAbsent || replyDensity != null) {
      map['reply_density'] = Variable<String>(replyDensity);
    }
    if (!nullToAbsent || likeLevel != null) {
      map['like_level'] = Variable<String>(likeLevel);
    }
    if (!nullToAbsent || humanLevel != null) {
      map['human_level'] = Variable<int>(humanLevel);
    }
    map['is_hot'] = Variable<bool>(isHot);
    map['like_count'] = Variable<int>(likeCount);
    map['comment_count'] = Variable<int>(commentCount);
    if (!nullToAbsent || likedAt != null) {
      map['liked_at'] = Variable<int>(likedAt);
    }
    if (!nullToAbsent || authorResidentId != null) {
      map['author_resident_id'] = Variable<String>(authorResidentId);
    }
    map['speech_by'] = Variable<String>(speechBy);
    if (!nullToAbsent || voicePath != null) {
      map['voice_path'] = Variable<String>(voicePath);
    }
    if (!nullToAbsent || speechDurationMs != null) {
      map['speech_duration_ms'] = Variable<int>(speechDurationMs);
    }
    return map;
  }

  PostsCompanion toCompanion(bool nullToAbsent) {
    return PostsCompanion(
      id: Value(id),
      content: Value(content),
      images: Value(images),
      createdAt: Value(createdAt),
      updatedAt: updatedAt == null && nullToAbsent
