class AiInteractionRow extends DataClass
    implements Insertable<AiInteractionRow> {
  final String id;
  final String postId;

  /// 说话的人。v3.0 之后可能是 `post_voices` 里的临时网民，
  /// 因此不再外键到 `ai_personas`（否则每个临时身份都要在固定住民表里
  /// 插一条影子行，把住民主页和关注列表一起污染）。
  final String personaId;

  /// like / comment / follow / message / repost
  final String type;

  /// text / voice / image / emoji
  final String? mediaType;
  final String? content;

  /// 图片评论配的一句话。表情包是内容、文字是“顺便说一句”，
  /// 两者可以同时存在——以前只存 content，发表情包就把文字吞了。
  final String? caption;
  final String? voicePath;
  final String? transcript;
  final int? voiceDurationMs;

  /// 住民“用语音说的”时记下它的 id（v4.0）；空 = 打字。
  /// 评论区只显示标签，不强行合成一段音频。
  final String speechBy;
  final int scheduledAt;
  final int? executedAt;

  /// pending / done / cancelled
  final String status;

  /// 这条互动从哪来：scheduled（随机排期）/ user_reply（接用户的话）/
  /// peer_reply（AI 接 AI）/ plan（策划脚本）。
  final String source;
  final bool isAi;
  final String scope;
  final String? parentId;

  /// 楼中楼里"回复 XXX"。用户自己的评论存在 user_comments 里，
  /// AI 的回复只能存在这里——不写的话界面上就只剩一条孤零零的回复。
  final String? replyToName;
  final int likeCount;
  final int? deletedAt;
  const AiInteractionRow({
    required this.id,
    required this.postId,
    required this.personaId,
    required this.type,
    this.mediaType,
    this.content,
    this.caption,
    this.voicePath,
    this.transcript,
    this.voiceDurationMs,
    required this.speechBy,
    required this.scheduledAt,
    this.executedAt,
    required this.status,
    required this.source,
    required this.isAi,
    required this.scope,
    this.parentId,
    this.replyToName,
    required this.likeCount,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['post_id'] = Variable<String>(postId);
    map['persona_id'] = Variable<String>(personaId);
    map['type'] = Variable<String>(type);
    if (!nullToAbsent || mediaType != null) {
      map['media_type'] = Variable<String>(mediaType);
    }
    if (!nullToAbsent || content != null) {
      map['content'] = Variable<String>(content);
    }
    if (!nullToAbsent || caption != null) {
      map['caption'] = Variable<String>(caption);
    }
    if (!nullToAbsent || voicePath != null) {
      map['voice_path'] = Variable<String>(voicePath);
    }
    if (!nullToAbsent || transcript != null) {
      map['transcript'] = Variable<String>(transcript);
    }
    if (!nullToAbsent || voiceDurationMs != null) {
      map['voice_duration_ms'] = Variable<int>(voiceDurationMs);
    }
    map['speech_by'] = Variable<String>(speechBy);
    map['scheduled_at'] = Variable<int>(scheduledAt);
    if (!nullToAbsent || executedAt != null) {
      map['executed_at'] = Variable<int>(executedAt);
    }
    map['status'] = Variable<String>(status);
    map['source'] = Variable<String>(source);
    map['is_ai'] = Variable<bool>(isAi);
    map['scope'] = Variable<String>(scope);
    if (!nullToAbsent || parentId != null) {
      map['parent_id'] = Variable<String>(parentId);
    }
    if (!nullToAbsent || replyToName != null) {
      map['reply_to_name'] = Variable<String>(replyToName);
    }
    map['like_count'] = Variable<int>(likeCount);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<int>(deletedAt);
    }
    return map;
  }

  AiInteractionsCompanion toCompanion(bool nullToAbsent) {
    return AiInteractionsCompanion(
      id: Value(id),
      postId: Value(postId),
      personaId: Value(personaId),
      type: Value(type),
      mediaType: mediaType == null && nullToAbsent
          ? const Value.absent()
          : Value(mediaType),
      content: content == null && nullToAbsent
          ? const Value.absent()
          : Value(content),
      caption: caption == null && nullToAbsent
          ? const Value.absent()
          : Value(caption),
      voicePath: voicePath == null && nullToAbsent
          ? const Value.absent()
          : Value(voicePath),
      transcript: transcript == null && nullToAbsent
          ? const Value.absent()
          : Value(transcript),
      voiceDurationMs: voiceDurationMs == null && nullToAbsent
          ? const Value.absent()
          : Value(voiceDurationMs),
      speechBy: Value(speechBy),
      scheduledAt: Value(scheduledAt),
      executedAt: executedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(executedAt),
      status: Value(status),
      source: Value(source),
      isAi: Value(isAi),
      scope: Value(scope),
      parentId: parentId == null && nullToAbsent
          ? const Value.absent()
          : Value(parentId),
      replyToName: replyToName == null && nullToAbsent
          ? const Value.absent()
          : Value(replyToName),
      likeCount: Value(likeCount),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
    );
