class NotificationLogRow extends DataClass
    implements Insertable<NotificationLogRow> {
  final String id;
  final String type;
  final String title;
  final String body;

  /// 这条通知指向的帖子（点击通知跳转用）。系统通知可以为空。
  final String? postId;
  final int? scheduledAt;
  final int? deliveredAt;
  final bool isRead;

  /// 同一类互动合并到哪一组。点赞用 `like:<postId>`：
  /// 一条帖子的多个赞只留一行通知，人数累加，而不是刷屏。
  final String groupKey;

  /// 这一组通知累计代表多少个人（一批 likeBatch 可能是 5 个人）。
  final int actorCount;

  /// 出现在标题里的名字，`|` 分隔，最多留三个。
  final String actorNames;
  final String scope;
  const NotificationLogRow({
    required this.id,
    required this.type,
    required this.title,
    required this.body,
    this.postId,
    this.scheduledAt,
    this.deliveredAt,
    required this.isRead,
    required this.groupKey,
    required this.actorCount,
    required this.actorNames,
    required this.scope,
  });
