  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['type'] = Variable<String>(type);
    map['title'] = Variable<String>(title);
    map['body'] = Variable<String>(body);
    if (!nullToAbsent || postId != null) {
      map['post_id'] = Variable<String>(postId);
    }
    if (!nullToAbsent || scheduledAt != null) {
      map['scheduled_at'] = Variable<int>(scheduledAt);
    }
    if (!nullToAbsent || deliveredAt != null) {
      map['delivered_at'] = Variable<int>(deliveredAt);
    }
    map['is_read'] = Variable<bool>(isRead);
    map['group_key'] = Variable<String>(groupKey);
    map['actor_count'] = Variable<int>(actorCount);
    map['actor_names'] = Variable<String>(actorNames);
    map['scope'] = Variable<String>(scope);
    return map;
  }

  NotificationLogsCompanion toCompanion(bool nullToAbsent) {
    return NotificationLogsCompanion(
      id: Value(id),
      type: Value(type),
      title: Value(title),
      body: Value(body),
      postId: postId == null && nullToAbsent
          ? const Value.absent()
          : Value(postId),
      scheduledAt: scheduledAt == null && nullToAbsent
          ? const Value.absent()
          : Value(scheduledAt),
      deliveredAt: deliveredAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deliveredAt),
      isRead: Value(isRead),
      groupKey: Value(groupKey),
      actorCount: Value(actorCount),
      actorNames: Value(actorNames),
      scope: Value(scope),
    );
  }

